changeSet.sql:
CREATE TABLE IF NOT EXISTS report.payment_reports ( id BIGSERIAL NOT NULL, payment_id BIGINT NOT NULL, client_id BIGINT NOT NULL, amount NUMERIC(15,2) NOT NULL, currency VARCHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, recipient_account VARCHAR(50), report_date DATE NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT pk_payment_reports PRIMARY KEY (id, report_date), CONSTRAINT uq_payment_reports_payment_id UNIQUE (payment_id, report_date) ) PARTITION BY RANGE (report_date);
COMMENT ON TABLE report.payment_reports IS 'Отчёты о платежах. Партиционировано по дням (report_date). client_id = Profile.id из profile-service (BIGINT).';
CREATE INDEX idx_payment_reports_client_date ON report.payment_reports (client_id, report_date);
CREATE INDEX idx_payment_reports_date ON report.payment_reports (report_date);
CREATE INDEX idx_payment_reports_status ON report.payment_reports (status, report_date);

-- Текущий месяц CREATE TABLE IF NOT EXISTS report.payment_reports_2026_04 PARTITION OF report.payment_reports FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
-- Следующий месяц CREATE TABLE IF NOT EXISTS report.payment_reports_2026_05 PARTITION OF report.payment_reports FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
-- Через два месяца CREATE TABLE IF NOT EXISTS report.payment_reports_2026_06 PARTITION OF report.payment_reports FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
-- Fallback-партиция для данных вне диапазона CREATE TABLE IF NOT EXISTS report.payment_reports_default PARTITION OF report.payment_reports DEFAULT;

changeSet.rollback:
DROP TABLE IF EXISTS report.payment_reports_2026_04;
DROP TABLE IF EXISTS report.payment_reports_2026_05;
DROP TABLE IF EXISTS report.payment_reports_2026_06;
DROP TABLE IF EXISTS report.payment_reports_default;

changeSet.sql:
CREATE TABLE IF NOT EXISTS report.transfer_reports ( id BIGSERIAL NOT NULL, transfer_id BIGINT NOT NULL, client_id BIGINT NOT NULL, transfer_type VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL, amount NUMERIC(15,2) NOT NULL, currency VARCHAR(3) NOT NULL, recipient_display VARCHAR(100), reason VARCHAR(500), report_date DATE NOT NULL, occurred_at TIMESTAMP NOT NULL, CONSTRAINT pk_transfer_reports PRIMARY KEY (id, report_date), CONSTRAINT uq_transfer_reports_transfer_id UNIQUE (transfer_id, report_date) ) PARTITION BY RANGE (report_date);
COMMENT ON TABLE report.transfer_reports IS 'Отчёты о переводах. Партиционировано по дням (report_date). client_id = Profile.id (BIGINT). status: CREATED/COMPLETED/BLOCKED/CANCELLED.';
CREATE INDEX idx_transfer_reports_client_date ON report.transfer_reports (client_id, report_date);
CREATE INDEX idx_transfer_reports_date ON report.transfer_reports (report_date);
CREATE INDEX idx_transfer_reports_type ON report.transfer_reports (transfer_type, report_date);

CREATE TABLE IF NOT EXISTS report.transfer_reports_2026_04
    PARTITION OF report.transfer_reports
    FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');

CREATE TABLE IF NOT EXISTS report.transfer_reports_2026_05
    PARTITION OF report.transfer_reports
    FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');

CREATE TABLE IF NOT EXISTS report.transfer_reports_2026_06
    PARTITION OF report.transfer_reports
    FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');

CREATE TABLE IF NOT EXISTS report.transfer_reports_default
    PARTITION OF report.transfer_reports DEFAULT;

changeSet.rollback:
DROP TABLE IF EXISTS report.transfer_reports_2026_04;
DROP TABLE IF EXISTS report.transfer_reports_2026_05;
DROP TABLE IF EXISTS report.transfer_reports_2026_06;
DROP TABLE IF EXISTS report.transfer_reports_default;
